// Clonado do Make. As abas sao lidas pelo n8n e viram linhas na mesma ordem de colunas do Make.
const HEAD = {"Afiliados": ["email", "ref", "titular", "whatsapp", "pix", "status", "cadastrado_em", "atualizado_em", "codigo", "codigo_expira", "tentativas", "sessao", "sessao_expira", "desativado_em"], "Visitantes": ["id_netliss", "nome", "whatsapp", "email", "sistema", "operadora", "modalidade", "data_entrada", "ultima_visita", "status_cliente", "status_teste", "usuario_teste", "data_teste", "gclid", "fbclid", "ttclid", "ref_indicador"], "Pagamentos": ["payment_id", "id_netliss", "tipo", "plano", "plan_id", "valor", "metodo", "status_pagamento", "data_criacao", "data_aprovacao", "usuario_entregue", "gclid", "conversao_google", "conversao_fb", "email", "ref_indicador", "cpf"], "Comissoes": ["payment_id", "lote", "ref", "email_afiliado", "id_netliss", "cpf", "valor_venda", "comissao", "lucro", "data_venda", "gerado_em"], "Lotes": ["lote", "ref", "email", "titular", "pix", "whatsapp", "referencia", "vendas", "valor", "status", "gerado_em", "pago_em"]};
const aba = n => [HEAD[n]].concat($('Ler ' + n).all().map(i => i.json).filter(r => r && r.row_number).map(r => HEAD[n].map(h => r[h] == null ? '' : String(r[h]))));
const input = { abas: ['Afiliados', 'Visitantes', 'Pagamentos', 'Comissoes', 'Lotes'].map(aba), avanco_ms: 0 };
// Netliss - Comissoes de afiliados (diario 10:30)
// Le Afiliados, Visitantes, Pagamentos, Comissoes e Lotes (ja lidos pelo Make) e monta:
// - as linhas novas de Comissoes e Lotes (o Make grava)
// - uma mensagem de Telegram por afiliado que tem comissao a receber (o Make envia com o botao Pix feito)
// Regra: 20% do PRIMEIRO pagamento de cada CPF, venda nova (tipo venda) aprovada a partir do inicio do programa,
// de visitante que chegou pelo link de afiliado ATIVO. Paga no dia seguinte: entra tudo aprovado ate ontem.
const NL = String.fromCharCode(10);
const TAXA = 0.20;
const INICIO = '2026-10-16'; // o programa vale daqui para frente
const out = { comissoes: [], lotes: [], mensagens: [] };

function txt(v) { return String(v == null ? '' : v).trim(); }
function lerJson(v) { if (v && typeof v === 'object') { return v; } try { return JSON.parse(String(v || 'null')); } catch (e) { return null; } }
function linhas(b) { b = lerJson(b); if (!b) { return []; } const v = Array.isArray(b) ? b : (b.values || []); return v.slice(1); }
function num(v) { const s = txt(v).replace('R$', '').trim(); if (!s) { return 0; } const t = s.indexOf(',') > -1 ? s.split('.').join('').replace(',', '.') : s; const n = Number(t); return isNaN(n) ? 0 : n; }
function p2(n) { n = Number(n || 0); return n < 10 ? '0' + n : String(n); }
function cent(n) { return Math.round(n * 100) / 100; }
function reais(n) { return 'R$ ' + cent(n).toFixed(2).replace('.', ','); }
function partesSP(ms) { const p = {}; for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms))) { p[x.type] = x.value; } return p; }
// "dd/mm/aaaa hh:mm" -> "aaaa-mm-dd hh:mm" (comparavel como texto)
function chave(br) { const s = txt(br); const m = s.match(/^([0-9]{2})[/]([0-9]{2})[/]([0-9]{4})(?:[ ]+([0-9]{2}):([0-9]{2}))?/); if (!m) { return ''; } return m[3] + '-' + m[2] + '-' + m[1] + ' ' + (m[4] || '00') + ':' + (m[5] || '00'); }

const abas = lerJson(input.abas) || [];
const afiliados = linhas(abas[0]), visitantes = linhas(abas[1]), pagamentos = linhas(abas[2]), comissoes = linhas(abas[3]), lotes = linhas(abas[4]);

const agora = Date.now() + Number(input.avanco_ms || 0);
const h = partesSP(agora);
const hoje = h.year + '-' + h.month + '-' + h.day;
const o = partesSP(agora - 86400000);
const ontem = o.year + '-' + o.month + '-' + o.day;
const ontemBR = o.day + '/' + o.month + '/' + o.year;
const agoraBR = h.day + '/' + h.month + '/' + h.year + ' ' + h.hour + ':' + h.minute;
const sufixo = h.year.slice(2) + h.month + h.day;

// afiliados ativos por codigo
const af = {};
for (const a of afiliados) { const ref = txt(a[1]).toUpperCase(); if (ref && txt(a[5]) !== 'desativado') { af[ref] = { email: txt(a[0]), ref: ref, titular: txt(a[2]), zap: txt(a[3]), pix: txt(a[4]) }; } }

// de onde veio cada visitante (Visitantes: 0 id, 7 data_entrada, 16 ref_indicador)
const refDe = {};
const visOntem = {};
for (const v of visitantes) {
  const ref = txt(v[16]).toUpperCase(); if (!ref) { continue; }
  refDe[txt(v[0])] = ref;
  if (chave(v[7]).slice(0, 10) === ontem) { visOntem[ref] = (visOntem[ref] || 0) + 1; }
}

// Pagamentos: 0 payment_id 1 id_netliss 2 tipo 5 valor 7 status 8 data_criacao 9 data_aprovacao 16 cpf
const jaFeito = {}; for (const c of comissoes) { jaFeito[txt(c[0])] = 1; }
const primeiraDoCpf = {};
const aprovados = [];
const testesOntem = {};
for (const p of pagamentos) {
  const tipo = txt(p[2]);
  if (tipo === 'teste_cliente' && chave(p[8]).slice(0, 10) === ontem) { const r = refDe[txt(p[1])]; if (r) { testesOntem[r] = (testesOntem[r] || 0) + 1; } }
  if (txt(p[7]) !== 'approved' || (tipo !== 'venda' && tipo !== 'renovacao')) { continue; }
  const quando = chave(p[9]) || chave(p[8]);
  // CORRECAO: a Liss nao pede CPF; sem CPF o cliente e identificado pelo e-mail (senao a venda da Liss nunca gera comissao)
  const cpf = txt(p[16]).replace(/[^0-9]/g, '') || txt(p[14]).toLowerCase();
  if (cpf) { if (!primeiraDoCpf[cpf] || quando < primeiraDoCpf[cpf].quando) { primeiraDoCpf[cpf] = { quando: quando, id: txt(p[0]) }; } }
  aprovados.push({ id: txt(p[0]), idn: txt(p[1]), tipo: tipo, valor: num(p[5]), quando: quando, cpf: cpf });
}

// vendas que geram comissao agora
const porRef = {};
for (const s of aprovados) {
  if (s.tipo !== 'venda' || !s.cpf || !s.id || jaFeito[s.id]) { continue; }
  const dia = s.quando.slice(0, 10);
  if (dia < INICIO || dia >= hoje) { continue; }
  if (!primeiraDoCpf[s.cpf] || primeiraDoCpf[s.cpf].id !== s.id) { continue; } // CPF que ja comprou antes = nao e cliente novo
  const ref = refDe[s.idn]; if (!ref || !af[ref]) { continue; }
  if (s.valor <= 0) { continue; }
  (porRef[ref] = porRef[ref] || []).push(s);
}

// historico (antes deste lote): Comissoes 2 ref 8 lucro ; Lotes 1 ref 8 valor 9 status
const lucroAntes = {}, pagoAntes = {};
for (const c of comissoes) { const r = txt(c[2]).toUpperCase(); lucroAntes[r] = (lucroAntes[r] || 0) + num(c[8]); }
for (const l of lotes) { const r = txt(l[1]).toUpperCase(); if (txt(l[9]) === 'paga') { pagoAntes[r] = (pagoAntes[r] || 0) + num(l[8]); } }

for (const ref of Object.keys(porRef)) {
  const a = af[ref]; const vendas = porRef[ref];
  const lote = 'AF' + sufixo + '-' + ref;
  let soma = 0, lucro = 0, vendasOntem = 0, lucroOntem = 0, comOntem = 0;
  const dias = {};
  for (const s of vendas) {
    const com = cent(s.valor * TAXA); const luc = cent(s.valor - com);
    soma += com; lucro += luc; dias[s.quando.slice(0, 10)] = 1;
    if (s.quando.slice(0, 10) === ontem) { vendasOntem++; lucroOntem += luc; comOntem += com; }
    out.comissoes.push([s.id, lote, ref, a.email, s.idn, s.cpf, cent(s.valor), com, luc, s.quando.slice(8, 10) + '/' + s.quando.slice(5, 7) + '/' + s.quando.slice(0, 4), agoraBR]);
  }
  soma = cent(soma);
  const ref_dias = Object.keys(dias).sort().map(d => d.slice(8, 10) + '/' + d.slice(5, 7)).join(', ');
  out.lotes.push([lote, ref, a.email, a.titular, a.pix, a.zap, ref_dias, vendas.length, soma, 'aguardando', agoraBR, '']);
  const atrasadas = vendas.length - vendasOntem;
  let m = '💰 COMISSÃO DE AFILIADO A PAGAR' + NL + 'Lote: ' + lote + NL + NL +
    '👤 ' + a.titular + NL + 'E-mail: ' + a.email + NL + 'WhatsApp: ' + a.zap + NL + 'Chave Pix: ' + a.pix + NL + 'Código: ' + ref + NL + NL +
    '📊 Ontem (' + ontemBR + ')' + NL +
    'Visitantes: ' + p2(visOntem[ref]) + NL + 'Testes: ' + p2(testesOntem[ref]) + NL + 'Vendas: ' + p2(vendasOntem) + NL +
    'Lucro do dia: ' + reais(lucroOntem) + NL + 'Comissão do dia: ' + reais(comOntem) + NL;
  if (atrasadas > 0) { m += NL + '⏳ Inclui ' + p2(atrasadas) + (atrasadas === 1 ? ' venda' : ' vendas') + ' de dias anteriores ainda não paga' + (atrasadas === 1 ? '' : 's') + ' (' + ref_dias + ').' + NL; }
  m += NL + '👉 PAGAR AGORA: ' + reais(soma) + ' (' + p2(vendas.length) + (vendas.length === 1 ? ' venda)' : ' vendas)') + NL + NL +
    '📈 Desde o início' + NL + 'Lucro total: ' + reais((lucroAntes[ref] || 0) + lucro) + NL + 'Já pago: ' + reais(pagoAntes[ref] || 0) + NL + NL +
    'Fez o Pix? Toque em ✅ Pix feito (ou responda esta mensagem com ok).';
  out.mensagens.push({ lote: lote, texto: m, teclado: JSON.stringify({ inline_keyboard: [[{ text: '✅ Pix feito', callback_data: 'afpago_' + lote }]] }) });
}

out.tem_comissoes = out.comissoes.length ? 'sim' : 'nao';
out.comissoes_corpo = JSON.stringify({ values: out.comissoes });
out.lotes_corpo = JSON.stringify({ values: out.lotes });
out.qtd = out.mensagens.length;
out.comissoes_obj = out.comissoes.map(l => Object.fromEntries(HEAD.Comissoes.map((h, i) => [h, l[i]])));
out.lotes_obj = out.lotes.map(l => Object.fromEntries(HEAD.Lotes.map((h, i) => [h, l[i]])));
return [{ json: out }];
